    def __init__(self):
        self.items = {}

    def add_item(self, item_id: str, name: str, price: float, quantity: int = 1) -> None:
        if not isinstance(price, (int, float)) or price < 0:
            raise ValueError("Price must be non-negative")
        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be an int greater than 0")

        if item_id in self.items:
            self.items[item_id]['quantity'] += quantity
        else:
            self.items[item_id] = {'name': name, 'price': price, 'quantity': quantity}

    def remove_item(self, item_id: str, quantity: int = 1) -> None:
        if item_id not in self.items:
            return

        if not isinstance(quantity, int) or quantity <= 0:
            raise ValueError("Quantity must be an int greater than 0")

        if self.items[item_id]['quantity'] <= quantity:
            del self.items[item_id]
        else:
            self.items[item_id]['quantity'] -= quantity

    def get_total(self) -> float:
        return sum(item['price'] * item['quantity'] for item in self.items.values())
